        elif type(demands) is list:
            customers = list(range(1, len(demands)))
        elif is_dict(instance):
            n = instance.get("n", instance.get("num_customers", 0))
            customers = list(range(1, n + 1))
        else:
            customers = []

    def demand_of(i):
        if type(demands) is dict:
            return demands.get(i, 0)
        if type(demands) is list:
            if 0 <= i < len(demands):
                return demands[i]
            return 0
        return 0

    def coord_of(i):
        if type(coords) is dict:
            return coords.get(i)
        if type(coords) is list:
            if 0 <= i < len(coords):
                return coords[i]
        return None

    def dist(i, j):
        if dist_matrix is not None:
            try:
                return dist_matrix[i][j]
            except Exception:
                try:
                    return dist_matrix[j][i]
                except Exception:
                    pass
        ci = coord_of(i)
        cj = coord_of(j)
        if ci is not None and cj is not None and len(ci) >= 2 and len(cj) >= 2:
            dx = ci[0] - cj[0]
            dy = ci[1] - cj[1]
            return (dx * dx + dy * dy) ** 0.5
        return abs(i - j)

    def route_load(route):
        s = 0
        for c in route:
            s += demand_of(c)
        return s

    def route_cost(route):
        if not route:
            return 0
        total = dist(depot, route[0])
        for idx in range(len(route) - 1):
            total += dist(route[idx], route[idx + 1])
        total += dist(route[-1], depot)
        return total

    def total_cost(routes):
        t = 0
        for r in routes:
            t += route_cost(r)
        return t

    def route_delta_insertion(route, pos, c):
        left = depot if pos == 0 else route[pos - 1]
        right = depot if pos == len(route) else route[pos]
        return dist(left, c) + dist(c, right) - dist(left, right)

    unserved = {}
    for c in customers:
        if c != depot:
            unserved[c] = True

    cust_sorted = list(customers)
    cust_sorted.sort(key=lambda c: (dist(depot, c), -demand_of(c), c))

    routes = []

    # Constructive phase: sequential insertion with nearest-neighbor bias.
    while unserved:
        start = None
        best_key = None
        for c in cust_sorted:
            if c in unserved:
                k = (dist(depot, c), -demand_of(c), c)
                if best_key is None or k < best_key:
                    best_key = k
                    start = c
        if start is None:
            break

        route = [start]
        del unserved[start]
        load = demand_of(start)
        last = start

        while True:
            best = None
            best_key = None
            for c in cust_sorted:
                if c not in unserved:
                    continue
                d = demand_of(c)
                if load + d > capacity:
                    continue
                k = (dist(last, c), dist(depot, c), -d, c)
                if best_key is None or k < best_key:
                    best_key = k
                    best = c
            if best is None:
                break
            route.append(best)
            del unserved[best]
            load += demand_of(best)
            last = best

        routes.append(route)

    # Repair phase: insert any leftover customers into feasible positions or new routes.
    if unserved:
        leftovers = list(unserved.keys())
        for c in leftovers:
            placed = False
            best_r = -1
            best_p = -1
            best_delta = None
            for r_idx in range(len(routes)):
                r = routes[r_idx]
                if route_load(r) + demand_of(c) > capacity:
                    continue
                for pos in range(len(r) + 1):
                    delta = route_delta_insertion(r, pos, c)
                    if best_delta is None or delta < best_delta or (delta == best_delta and (r_idx, pos, c) < (best_r, best_p, c)):
                        best_delta = delta
                        best_r = r_idx
                        best_p = pos
            if best_r >= 0:
                routes[best_r].insert(best_p, c)
                placed = True
            if not placed:
                routes.append([c])
            if c in unserved:
                del unserved[c]

    # Local search: intra-route 2-opt and simple relocation.
    improved = True
    iterations = 0
    while improved and iterations < 4:
        improved = False
        iterations += 1

        # 2-opt inside routes
        for r_idx in range(len(routes)):
            r = routes[r_idx]
            n = len(r)
            if n < 4:
                continue
            changed = True
            while changed:
                changed = False
                current = route_cost(r)
                for i in range(n - 2):
                    for j in range(i + 2, n):
                        if i == 0 and j == n - 1:
                            continue
                        nr = r[:i + 1] + r[i + 1:j + 1][::-1] + r[j + 1:]
                        new_cost = route_cost(nr)
                        if new_cost + 1e-12 < current:
                            r[:] = nr
                            current = new_cost
                            changed = True
                            improved = True
                            break
                    if changed:
                        break

        # Relocate customers between routes
        for a in range(len(routes)):
            if a >= len(routes):
                break
            ra = routes[a]
            i = 0
            while i < len(ra):
                c = ra[i]
                best_move = None
                best_gain = 0
                for b in range(len(routes)):
                    if a == b:
                        continue
                    rb = routes[b]
                    if route_load(rb) + demand_of(c) > capacity:
                        continue
                    remove_left = depot if i == 0 else ra[i - 1]
                    remove_right = depot if i == len(ra) - 1 else ra[i + 1]
                    removal_gain = dist(remove_left, c) + dist(c, remove_right) - dist(remove_left, remove_right)
                    for pos in range(len(rb) + 1):
                        insertion_delta = route_delta_insertion(rb, pos, c)
                        gain = removal_gain - insertion_delta
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_move = (b, pos)
                if best_move is not None and best_gain > 1e-12:
                    b, pos = best_move
                    customer = ra.pop(i)
                    if a < b:
                        b -= 0 if a != b else 0
                    routes[b].insert(pos, customer)
                    improved = True
                    if len(ra) == 0:
                        routes.pop(a)
                        break
                else:
                    i += 1

    # Final cleanup: remove any empty routes and ensure all customers exactly once.
    cleaned = []
    seen = {}
    for r in routes:
        nr = []
        for c in r:
            if c == depot:
                continue
            if c not in seen:
                seen[c] = True
                nr.append(c)
        if nr:
            cleaned.append(nr)

    missing = []
    for c in customers:
        if c != depot and c not in seen:
            missing.append(c)

    for c in missing:
        best_r = -1
        best_p = -1
        best_delta = None
        for r_idx in range(len(cleaned)):
            r = cleaned[r_idx]
            if route_load(r) + demand_of(c) > capacity:
                continue
            for pos in range(len(r) + 1):
                delta = route_delta_insertion(r, pos, c)
                if best_delta is None or delta < best_delta:
                    best_delta = delta
                    best_r = r_idx
                    best_p = pos
        if best_r >= 0:
            cleaned[best_r].insert(best_p, c)
        else:
            cleaned.append([c])

    return cleaned
